    for (y,x) in big: T[y-r0][x-c0]=g[y][x]
    ch=(th-1)//2; cw=(tw-1)//2
    out=[[bg]*w for _ in range(h)]
    for (y,x) in big: out[y][x]=g[y][x]
    for c in cls:
        if len(c)>1: continue
        (di,dj)=next(iter(c))
        sy,sx=di-ch,dj-cw
        for rr in range(th):
            for cc in range(tw):
                yy,yx=sy+rr,sx+cc
                if 0<=yy<h and 0<=yx<w: out[yy][yx]=T[rr][cc]
    return out

